<template>
  <section ref="section" class="contact-portal" :style="{ height: `${stages.length * 108}vh` }"><div class="contact-portal__sticky" :style="{ '--contact': active.color }"><div class="contact-portal__stars"></div><div class="contact-portal__portal" :style="{ '--turn': `${progress * 260}deg` }" aria-hidden="true"><span v-for="ring in 4" :key="ring" class="contact-portal__ring"></span><div class="contact-portal__packet"><i></i><b>✦</b></div><div class="contact-portal__route"></div></div><div class="contact-portal__copy container mx-auto px-6 sm:px-10"><p>OPEN CHANNEL / LET'S CONNECT</p><Transition name="contact-copy" mode="out-in"><article :key="active.id"><small>{{ active.label }}</small><h2 v-html="active.title"></h2><p>{{ active.body }}</p><span>{{ active.code }}</span></article></Transition></div><div class="contact-portal__status"><i></i> CHANNEL {{ String(activeIndex + 1).padStart(2,'0') }} / ONLINE</div></div></section>
</template>
<script setup>
import { computed,onMounted,onUnmounted,ref } from 'vue';
const stages=[{id:'hello',label:'01 / INITIATE',title:'一個想法，<br>就是訊號的起點。',body:'無論是技術交流、合作機會，或一個還在發芽的專案構想，都歡迎把訊息送進這個頻道。',code:'CHANNEL_READY',color:'#38e8c4'},{id:'connect',label:'02 / TRANSMIT',title:'讓對話，<br>跨越距離抵達。',body:'每個訊息都像一個資料封包，穿越雜訊與距離，找到能一起把想法做成現實的人。',code:'PACKET_IN_FLIGHT',color:'#36b5ff'},{id:'reply',label:'03 / RESPOND',title:'下一段連線，<br>從你的訊息開始。',body:'留下你的聯絡方式與想說的事；我會閱讀、回覆，並期待這條連線往下一個可能前進。',code:'HANDSHAKE_COMPLETE',color:'#ca8cff'}];
const section=ref(null),progress=ref(0),activeIndex=ref(0);let raf=null;const active=computed(()=>stages[activeIndex.value]);const update=()=>{raf=null;const r=section.value?.getBoundingClientRect();if(!r)return;const range=r.height-innerHeight;progress.value=range>0?Math.min(1,Math.max(0,-r.top/range)):0;activeIndex.value=Math.min(2,Math.floor(progress.value*3));};const scroll=()=>{if(raf===null)raf=requestAnimationFrame(update)};onMounted(()=>{update();addEventListener('scroll',scroll,{passive:true});addEventListener('resize',scroll)});onUnmounted(()=>{removeEventListener('scroll',scroll);removeEventListener('resize',scroll);if(raf)cancelAnimationFrame(raf)});
</script>
