-spacing:-.06em}.contact-portal article>p{max-width:465px;margin-top:23px;color:#c3cad5;line-height:1.85}.contact-portal article>span{display:inline-block;margin-top:23px;padding:8px 10px;border:1px solid color-mix(in srgb,var(--contact) 42%,transparent);background:rgba(5,7,14,.5)}.contact-portal__status{position:absolute;right:26px;bottom:24px;z-index:4;color:#aab1c1;font:10px/1 ui-monospace,monospace;letter-spacing:.11em}.contact-portal__status i{display:inline-block;width:7px;height:7px;margin-right:7px;border-radius:50%;background:var(--contact);box-shadow:0 0 10px var(--contact);animation:status 1.2s steps(2) infinite}.contact-copy-enter-active,.contact-copy-leave-active{transition:opacity .3s,transform .35s}.contact-copy-enter-from{opacity:0;transform:translateY(16px)}.contact-copy-leave-to{opacity:0;transform:translateY(-12px)}@keyframes status{50%{opacity:.25}}@media(max-width:700px){.contact-portal__portal{width:85vw;right:-26vw;top:65%;opacity:.64}.contact-portal__copy{align-self:flex-start;padding-top:17vh}.contact-portal h2{font-size:clamp(2.6rem,13vw,4.4rem);max-width:18rem}.contact-portal article>p{max-width:19rem}.contact-portal__status{right:14px;bottom:18px;font-size:8px}}@media(prefers-reduced-motion:reduce){.contact-portal__status i{animation:none}.contact-copy-enter-active,.contact-copy-leave-active{transition:none}}
</style>
